function compressedString(word) {
  const parts = [];
  let i = 0;

  while (i < word.length) {
    const letter = word[i];
    let run = 0;
    while (i < word.length && word[i] === letter && run < 9) {
      run++;
      i++;
    }
    parts.push(String(run) + letter);
  }
  return parts.join('');
}

brute:
function compressedString(word) {
  // A regular expression takes a character plus up to 8 more copies of it, greedily, from left to right.
  return word.replace(/(.)\1{0,8}/g, (block) => block.length + block[0]);
}

