function generate(rand, size) {
  const large = size === 'large';
  const target = large ? 9000 + Math.floor(rand() * 1001) : 1 + Math.floor(rand() * 30);
  // One letter only, or a few letters (small) / many letters (large), in short or long runs.
  const letters = rand() < 0.15 ? 1 : large ? 2 + Math.floor(rand() * 25) : 2 + Math.floor(rand() * 3);
  const longest = rand() < 0.5 ? 3 : 25;
  let word = '';
  while (word.length < target) {
    const letter = String.fromCharCode(97 + Math.floor(rand() * letters));
    word += letter.repeat(1 + Math.floor(rand() * longest));
  }
  return [word.slice(0, target)];
}
